        import wikitextparser as wtp

        # Parse the template to get the template name
        try:
            parsed = wtp.parse(tpl)
            if parsed.templates:
                template_obj = parsed.templates[0]
                template_name = template_obj.name.strip()

                # Check if this is a form-of template that should extract base word
                if template_name in form_of_templates:
                    # Extract arguments 
                    args = [arg.value for arg in template_obj.arguments]
                    # For form-of templates, the base word is typically the 3rd argument (index 2)
