                    if len(args) >= 2:
                        base_word = args[1]  # Second argument is the base word
                        if base_word and base_word != word:
                            variants.append(base_word)
                            return
        except Exception:
            # If parsing fails, fall back to normal processing
            pass

    # Normal processing for other cases
    if (variant := process_templates(word, tpl, locale)) and variant != word:
        variants.append(variant)

